void vb_dispatch_call(CPUState* cpu, uint32_t target_pc, uint32_t lp) {
    /* JAL semantic: writeback the link register and enter
     * the dispatch loop with the JAL's fall-through PC as
     * the saved_lp gate. The callee's eventual JMP r31
     * returns control here when cpu->pc == lp. */
    cpu->gpr[31] = lp;
    cpu->pc = target_pc;
    vb_dispatch_loop(cpu, lp);
}

void vb_dispatch(CPUState* cpu, uint32_t target_pc) {
    /* Top-level entry from main.cpp.
     *
     * Critical: this MUST NOT touch cpu->gpr[31]. Yielded
     * resumes (step-budget exhaustion mid-cart) re-enter
     * through here on every main-loop pass, and the cart's
     * live r31 — set by past JALs and saved/restored across
     * cart-side function prologues — must survive across
     * yields. Clobbering r31 here breaks every JMP r31 the
     * cart issues after the first yield, unwinding control
     * to the sentinel and halting the cart prematurely.
     *
     * The sentinel-equal-r31 invariant for top-level return
     * detection is established by main.cpp once after
     * vb_cpu_reset (cpu.gpr[31] = VB_TOP_LEVEL_LP) and
     * preserved by cart-side stack push/pop discipline. */
    cpu->pc = target_pc;
    vb_dispatch_loop(cpu, VB_TOP_LEVEL_LP);
}

/* CRC32 of the ROM this recompiler run was generated from.
 * main.cpp computes the CRC32 of the file it loads and compares;
 * a mismatch means the user provided a different cart than the
 * one this binary was built for. */
uint32_t vb_game_expected_crc32(void) { return 0x7CE7460Du; }